{"path":"events.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Ceremonies & Calendar — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Find the next restorative sound gathering and reserve your seat. Cohort sessions, intentional practices, and a quick try-it-now guide to feel the first inhale.">
  <style>
    :root{--bg:#0f1720;--card:#0f1a24;--muted:#9aa6b2;--accent:#7ee0d6;--glass:rgba(255,255,255,0.04);--gold:#ffdca3}
    *{box-sizing:border-box}html,body{height:100%}body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;line-height:1.3;background:linear-gradient(180deg,#081018 0%,#07121a 100%);color:#e6f2ef}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;border-bottom:1px solid rgba(255,255,255,0.03)}
    .brand{display:flex;gap:14px;align-items:center}
    .logo{width:48px;height:48px;border-radius:10px;background:radial-gradient(circle at 30% 20%,var(--accent),rgba(255,255,255,0.03) 40%),linear-gradient(180deg,#062e2a,#052025);display:flex;align-items:center;justify-content:center;font-weight:700;color:#002;box-shadow:0 6px 18px rgba(0,0,0,0.5)}
    nav a{color:var(--muted);text-decoration:none;margin-left:18px;font-weight:600}
    nav a:hover{color:var(--accent)}
    main{padding:28px;max-width:1100px;margin:20px auto}
    .row{display:grid;grid-template-columns:1fr 360px;gap:28px}
    .hero{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:22px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)}
    .hero h1{margin:0 0 6px;font-size:22px;color:#eaf6f2}
    .hero p{margin:0;color:var(--muted)}
    .next-event{margin-top:16px;padding:18px;background:var(--card);border-radius:10px;border:1px solid rgba(255,255,255,0.02)}
    .date{font-weight:700;color:var(--gold);letter-spacing:.6px}
    .meta{display:flex;gap:12px;color:var(--muted);margin-top:8px}
    .seat-map{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;margin-top:12px}
    .seat{background:var(--glass);height:36px;border-radius:8px;border:1px solid rgba(255,255,255,0.03);display:flex;align-items:center;justify-content:center;color:var(--muted);cursor:pointer}
    .seat.selected{background:linear-gradient(180deg,rgba(126,224,214,.14),rgba(126,224,214,.04));border-color:rgba(126,224,214,.25);color:#002}
    .seat.taken{background:linear-gradient(180deg,rgba(255,255,255,.03),rgba(255,255,255,.01));opacity:0.35;cursor:not-allowed}
    .cta{margin-top:12px;display:flex;gap:10px}
    .btn{background:linear-gradient(90deg,var(--accent),#5bd2c4);border:none;padding:10px 14px;border-radius:10px;cursor:pointer;font-weight:700;color:#043;box-shadow:0 6px 18px rgba(126,224,214,0.08)}
    .ghost{background:transparent;border:1px solid rgba(255,255,255,0.06);color:var(--muted)}
    .calendar{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:18px}
    .event-card{background:rgba(255,255,255,0.02);padding:14px;border-radius:10px;border:1px solid rgba(255,255,255,0.03)}
    .pack{margin-top:20px;padding:16px;border-radius:10px;background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent);border:1px solid rgba(255,255,255,0.02)}
    .pack label{display:block;color:var(--muted);margin-bottom:6px}
    .pack .options{display:flex;gap:8px;flex-wrap:wrap}
    .chip{background:rgba(255,255,255,0.02);padding:8px 10px;border-radius:999px;border:1px solid rgba(255,255,255,0.02);color:var(--muted);cursor:pointer}
    .chip.active{background:linear-gradient(90deg,var(--accent),#8beadc);color:#012}
    .outcome{margin-top:12px;color:var(--muted);font-size:14px}
    footer{padding:20px 28px;margin-top:20px;color:var(--muted);font-size:13px;text-align:center}
    /* modal */
    .modal{position:fixed;inset:0;background:rgba(2,6,10,0.7);display:none;align-items:center;justify-content:center;padding:20px}
    .modal.show{display:flex}
    .modal-card{width:100%;max-width:740px;background:linear-gradient(180deg,#04202a,#06262e);border-radius:12px;padding:20px;border:1px solid rgba(255,255,255,0.03);box-shadow:0 30px 80px rgba(2,6,10,0.7)}
    .guide-visual{width:120px;height:120px;border-radius:999px;margin:6px auto;background:radial-gradient(circle at 40% 40%,var(--accent),transparent 40%);display:flex;align-items:center;justify-content:center;color:#012;font-weight:700}
    .timer{font-size:36px;text-align:center;margin-top:8px}
    .small{font-size:13px;color:var(--muted)}
    .disclaimer{margin-top:12px;padding:12px;border-radius:8px;background:rgba(255,255,255,0.02);color:var(--muted);font-size:13px}
    @media (max-width:900px){.row{grid-template-columns:1fr;}.calendar{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">SB</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Calendar</a>
      <a href="private-sessions.html">Private Offerings</a>
      <a href="pricing.html">Invest</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>
  <main>
    <div class="row">
      <section class="hero">
        <h1>Upcoming Ceremony — pick your place</h1>
        <p>Join a cohort-level sound session where a small group traces a gentle arc of attention. Reserve a spot, prep with our quick packing helper, or try a mini-exercise instantly to get present.</p>

        <div class="next-event" id="nextEvent">
          <div class="date" id="neDate">Sat, Mar 6 • 6:30pm</div>
          <div class="meta"><div id="neVenue">Studio — {{CITY}}, {{STATE}}</div><div>Capacity: <span id="neCap">12</span></div></div>

          <div class="seat-map" id="seatMap" aria-label="seat map">
            <!-- seats rendered by JS -->
          </div>

          <div class="cta">
            <button class="btn" id="reserveBtn">Reserve selected</button>
            <button class="ghost" id="tryBtn">Try it now</button>
          </div>
          <div class="outcome" id="reserveOutcome"></div>
        </div>

        <div class="calendar" id="calendarList">
          <!-- calendar items populated by JS -->
        </div>

      </section>

      <aside>
        <div class="pack">
          <label for="prefs">Packing & what-to-bring generator</label>
          <div class="options" id="prefs">
            <div class="chip" data-key="mat">Small cushion or mat</div>
            <div class="chip" data-key="blanket">Warm blanket</div>
            <div class="chip" data-key="pillow">Neck pillow</div>
            <div class="chip" data-key="mask">Eye mask</div>
            <div class="chip" data-key="water">Water bottle</div>
            <div class="chip" data-key="notebook">Notebook + pen</div>
            <div class="chip" data-key="headphones">Soft earplugs</div>
          </div>
          <div style="margin-top:10px;display:flex;gap:8px"><button class="btn" id="makeList">Make my list</button><button class="ghost" id="shortList">Surprise me</button></div>
          <div class="outcome" id="packOutcome">We’ll suggest essentials tuned to your picks.</div>
        </div>

        <div class="disclaimer">
          <strong>Contraindications & note:</strong>
          If you have epilepsy, recent head surgery, are pregnant, using medical devices (e.g., pacemakers), or have serious psychiatric conditions, consult your healthcare provider before attending. Sound experiences can be intense; reach out for accommodations via <a href="mailto:{{EMAIL}}" style="color:var(--accent)">{{EMAIL}}</a>.
        </div>
      </aside>
    </div>
  </main>

  <div class="modal" id="modal">
    <div class="modal-card" role="dialog" aria-modal="true" aria-labelledby="modalTitle">
      <h2 id="modalTitle">Quick: A two-minute presence guide</h2>
      <div class="guide-visual" id="pulse">•</div>
      <div class="timer" id="timer">02:00</div>
      <div class="small" id="phase">Phase: Centering — gentle breath</div>
      <div style="display:flex;gap:8px;justify-content:center;margin-top:12px">
        <button class="btn" id="startGuide">Begin</button>
        <button class="ghost" id="closeGuide">Close</button>
      </div>
      <div style="margin-top:12px">
        <label class="small">Journal prompt (optional)</label>
        <textarea id="journal" placeholder="A short intention — 1–2 lines" style="width:100%;min-height:80px;border-radius:8px;padding:8px;background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.02);color:inherit"></textarea>
      </div>
    </div>
  </div>

  <footer>
    <div style="margin-bottom:6px">Call us: <strong>{{PHONE}}</strong> • <a href="mailto:{{EMAIL}}" style="color:var(--accent)">{{EMAIL}}</a></div>
    <div class="small">Small cohorts. Generous space. Reach us to request accessible seating.</div>
  </footer>

  <script>
    // Simple data for events
    const events = [
      {id:1,date:'2026-03-06T18:30:00',label:'Evening Resonance (Cohort A)',capacity:12,taken:[2,5]},
      {id:2,date:'2026-03-13T10:00:00',label:'Morning Field (Cohort B)',capacity:10,taken:[1,3,4]},
      {id:3,date:'2026-03-20T18:30:00',label:'Deep Rest Series',capacity:14,taken:[]}
    ];

    // render calendar list
    const calendarList = document.getElementById('calendarList');
    events.forEach(ev=>{
      const d = new Date(ev.date);
      const card = document.createElement('div');card.className='event-card';
      card.innerHTML = `<div style=\"font-weight:700;color:var(--gold)\">${ev.label}</div><div class=\"small\">${d.toLocaleString()} — Capacity ${ev.capacity}</div><div style=\"margin-top:8px;display:flex;gap:8px\"><button class=\"btn\" onclick=\"openFor(${ev.id})\">View & Reserve</button><button class=\"ghost\" onclick=\"preview(${ev.id})\">Preview guide</button></div>`;
      calendarList.appendChild(card);
    });

    // next event defaults to first
    let current = events[0];
    document.getElementById('neDate').textContent = new Date(current.date).toLocaleString();
    document.getElementById('neCap').textContent = current.capacity;

    const seatMap = document.getElementById('seatMap');
    function renderSeats(ev){
      seatMap.innerHTML='';
      for(let i=1;i<=ev.capacity;i++){
        const s=document.createElement('div');s.className='seat';s.textContent=i;
        if(ev.taken.includes(i)) s.classList.add('taken');
        s.dataset.seat=i;
        s.addEventListener('click',()=>toggleSeat(ev,i,s));
        seatMap.appendChild(s);
      }
    }

    function toggleSeat(ev,i,el){
      if(el.classList.contains('taken')) return;
      el.classList.toggle('selected');
      updateOutcome();
    }

    function updateOutcome(){
      const sel = [...seatMap.querySelectorAll('.seat.selected')].map(n=>n.dataset.seat);
      const out = document.getElementById('reserveOutcome');
      if(sel.length===0) out.textContent='No seats selected yet.'; else out.textContent=`Selected seat(s): ${sel.join(', ')} — click Reserve to confirm (local only).`;
    }

    renderSeats(current);
    updateOutcome();

    document.getElementById('reserveBtn').addEventListener('click',()=>{
      const sel = [...seatMap.querySelectorAll('.seat.selected')].map(n=>Number(n.dataset.seat));
      if(sel.length===0){alert('Select at least one seat.');return}
      // fake reserve
      current.taken.push(...sel);
      renderSeats(current);
      document.getElementById('reserveOutcome').textContent='Reserved locally: '+sel.join(', ')+'. We will follow up to confirm.';
    });

    // quick open event
    window.openFor=function(id){
      const ev = events.find(e=>e.id===id);current=ev;document.getElementById('neDate').textContent=new Date(ev.date).toLocaleString();document.getElementById('neCap').textContent=ev.capacity;renderSeats(ev);updateOutcome();window.scrollTo({top:0,behavior:'smooth'})
    }
    window.preview=function(id){openModal();}

    // Packing list generator
    const chips = document.querySelectorAll('.chip');
    chips.forEach(ch=>ch.addEventListener('click',()=>ch.classList.toggle('active')));
    document.getElementById('makeList').addEventListener('click',()=>{
      const picks=[...document.querySelectorAll('.chip.active')].map(n=>n.dataset.key);
      const mapping={
        mat:'Small cushion or yoga mat — portable, soft, and quick to roll',
        blanket:'Light warm blanket — evenings can get cool',
        pillow:'Neck or travel pillow for spinal comfort',
        mask:'Comfortable eye mask to ease visual rest',
        water:'Reusable water bottle — hydrate before and after',
        notebook:'Pocket notebook & pen — for a short reflection',
        headphones:'Soft earplugs if you prefer attenuated highs'
      };
      const out = picks.length? picks.map(p=>mapping[p]).join('\n') : 'No picks selected. Consider: blanket, cushion, and water.';
      document.getElementById('packOutcome').textContent = out;
    });
    document.getElementById('shortList').addEventListener('click',()=>{
      const options=['Blanket','Neck pillow','Notebook','Water bottle'];
      const pick = options[Math.floor(Math.random()*options.length)];
      document.getElementById('packOutcome').textContent = `Try bringing: ${pick} — and arrive 10 minutes early.`;
    });

    // Modal guide
    const modal = document.getElementById('modal');
    const tryBtn = document.getElementById('tryBtn');
    const closeGuide = document.getElementById('closeGuide');
    const startGuide = document.getElementById('startGuide');
    const timerEl = document.getElementById('timer');
    const phaseEl = document.getElementById('phase');
    const pulse = document.getElementById('pulse');
    let timerInterval=null;let remaining=120; // seconds

    function formatTime(s){const m=Math.floor(s/60);const sec=s%60;return `${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}`;}
    function openModal(){modal.classList.add('show');remaining=120;timerEl.textContent=formatTime(remaining);phaseEl.textContent='Phase: Centering — gentle breath';pulse.style.transform='scale(1)';document.getElementById('journal').value='';}
    function closeModal(){modal.classList.remove('show');clearInterval(timerInterval);timerInterval=null}
    tryBtn.addEventListener('click',openModal);closeGuide.addEventListener('click',closeModal);
    startGuide.addEventListener('click',()=>{
      if(timerInterval){clearInterval(timerInterval);timerInterval=null;startGuide.textContent='Begin';return}
      startGuide.textContent='Pause';let phase=0; // 0 center 1 breathing 2 journaling
      timerInterval=setInterval(()=>{
        remaining--;timerEl.textContent=formatTime(remaining);
        // simple phase transitions
        if(remaining>90){phase=0;phaseEl.textContent='Phase: Center — settle your shoulders';pulse.style.transform=`scale(${1 + (120-remaining)/60 * 0.15})`}
        else if(remaining>30){phase=1;phaseEl.textContent='Phase: Breathe — 4 in, 6 out (soft)';pulse.style.transform=`scale(${1 + Math.sin((120-remaining)/4)*0.25})`}
        else {phase=2;phaseEl.textContent='Phase: Set an intention — write 1–2 lines';pulse.style.transform=`scale(${1 + ((30-remaining)/30)*0.18})`}
        if(remaining<=0){clearInterval(timerInterval);timerInterval=null;phaseEl.textContent='Done — carry this with you.';startGuide.textContent='Begin'}
      },1000);
    });

    // close if background clicked
    modal.addEventListener('click',(e)=>{if(e.target===modal)closeModal()});

    // init
    document.addEventListener('DOMContentLoaded',()=>{
      // nothing for now
    });
  </script>
</body>
</html>"} 
{"path":"private-sessions.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Private Offerings — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Book personalized sound sessions, small group cohorts, or consulting for workplace wellbeing. Tailored ceremonies for individuals and private groups.">
  <style>
    :root{--bg:#07121a;--card:#071824;--muted:#9fb0b7;--accent:#9be7d9;--pearl:#f3e6d8}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;background:linear-gradient(0deg,#031018 0%,#052022 100%);color:#e9fbf6}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 26px}
    .logo{width:44px;height:44px;border-radius:9px;background:linear-gradient(180deg,#083632,#042a2a);display:flex;align-items:center;justify-content:center;font-weight:800}
    nav a{color:var(--muted);margin-left:16px;text-decoration:none}
    main{max-width:980px;margin:20px auto;padding:20px}
    .intro{display:flex;gap:18px;align-items:flex-start}
    .story{flex:1;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)}
    .aside{width:300px}
    h1{margin:0 0 8px}
    .muted{color:var(--muted)}
    .offer{margin-top:12px;padding:14px;border-radius:10px;background:var(--card);border:1px solid rgba(255,255,255,0.03)}
    .offer h3{margin:0 0 6px}
    .controls{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}
    .select,button{padding:8px 10px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:inherit}
    .reserve{background:linear-gradient(90deg,var(--accent),#6be2d0);color:#012;border:none;font-weight:800}
    .seat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:10px}
    .slot{padding:8px;border-radius:8px;background:rgba(255,255,255,0.02);text-align:center;cursor:pointer}
    .slot.taken{opacity:0.35;cursor:not-allowed}
    .slot.selected{outline:3px solid rgba(155,231,217,0.15);background:linear-gradient(90deg,rgba(155,231,217,0.09),transparent)}
    .note{font-size:13px;color:var(--muted);margin-top:8px}
    .modal{position:fixed;inset:0;background:rgba(1,8,12,0.7);display:none;align-items:center;justify-content:center}
    .modal.show{display:flex}
    .modal-card{width:100%;max-width:680px;background:linear-gradient(180deg,#04242a,#042a2e);padding:20px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)}
    .guide-visual{height:90px;border-radius:10px;background:linear-gradient(90deg,rgba(155,231,217,0.08),transparent);display:flex;align-items:center;justify-content:center}
    .disclaimer{margin-top:12px;padding:10px;background:rgba(255,255,255,0.02);border-radius:8px;color:var(--muted)}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px"><div class="logo">P</div><div style="font-weight:700">{{BUSINESS_NAME}}</div></div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Ceremonies</a>
      <a href="private-sessions.html">Private Offerings</a>
      <a href="pricing.html">Pricing</a>
      <a href="book.html">Book</a>
    </nav>
  </header>
  <main>
    <div class="intro">
      <div class="story">
        <h1>Private Sessions & Group Pods</h1>
        <p class="muted">Tailored sound for one person, couples, or intimate teams. Choose a duration, add focused intention work, and invite a small group. We offer facilitated approaches for stress release, pre-sleep routines, and workplace micro-retreats.</p>

        <div class="offer">
          <h3>Private: Solo Resonance</h3>
          <div class="muted">45 minutes • Small, one-on-one session with custom sound selections</div>
          <div class="controls">
            <label class="muted">Preferred date</label>
            <input type="date" id="privateDate" class="select">
            <label class="muted">Duration</label>
            <select id="privateDur" class="select"><option value="30">30 min</option><option value="45" selected>45 min</option><option value="60">60 min</option></select>
          </div>
          <div class="note">Select a slot below to tentatively hold time. This is a local reservation only; our team will confirm.</div>

          <div class="seat-grid" id="privateSlots">
            <!-- slots populated by JS -->
          </div>

          <div style="margin-top:10px;display:flex;gap:8px"><button class="reserve" id="holdPrivate">Hold this time</button><button class="select" id="previewGuide">Try a guided moment</button></div>
          <div class="disclaimer">If you have medical implants, epilepsy, or are pregnant, please contact us before booking. For clinical conditions, consult a practitioner.</div>
        </div>

      </div>

      <aside class="aside">
        <div style="background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:14px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)">
          <h4 style="margin:0 0 8px">Why choose private?</h4>
          <ul style="color:var(--muted);padding-left:18px;margin:0 0 8px">
            <li>Personalized sound palette</li>
            <li>Intention-setting conversation before sound</li>
            <li>Adaptations for mobility and comfort</li>
          </ul>
          <div style="display:flex;gap:8px"><a class="reserve" href="mailto:{{EMAIL}}">Contact us</a><a class="select" href="book.html">Book</a></div>
        </div>

        <div class="disclaimer" style="margin-top:12px">
          <strong>Contraindications:</strong> Loud vibrations can be challenging for people with seizure disorders, those using cochlear implants, or during pregnancy without clearance. Reach out to discuss safe alternatives.
        </div>
      </aside>
    </div>

    <!-- modal guide (repeat of events style but different text) -->
    <div class="modal" id="modalGuide">
      <div class="modal-card">
        <h2>Mini Practice: set an intention</h2>
        <div class="guide-visual">Breathe → Listen</div>
        <p class="muted">A brief hand-crafted practice to steady attention before a private session. Gentle breath, one-line intention, soft listening.</p>
        <div style="display:flex;gap:8px;margin-top:10px"><button class="reserve" id="startMini">Start</button><button class="select" id="closeMini">Close</button></div>
      </div>
    </div>

  </main>
  <footer style="padding:18px;text-align:center;color:var(--muted)">Questions? Email <a href="mailto:{{EMAIL}}" style="color:var(--accent)">{{EMAIL}}</a> or call <strong>{{PHONE}}</strong></footer>

  <script>
    // Private slots logic
    const slots = [
      {id:1,time:'09:00',taken:false},
      {id:2,time:'10:30',taken:true},
      {id:3,time:'12:00',taken:false},
      {id:4,time:'14:00',taken:false},
      {id:5,time:'16:00',taken:false},
      {id:6,time:'18:00',taken:true}
    ];
    const grid = document.getElementById('privateSlots');
    let chosenSlot=null;
    function renderSlots(){
      grid.innerHTML='';
      slots.forEach(s=>{
        const d=document.createElement('div');d.className='slot'+(s.taken?' taken':'');d.textContent=s.time;d.dataset.id=s.id;
        d.addEventListener('click',()=>selectSlot(s,d));grid.appendChild(d);
      });
    }
    function selectSlot(s,el){
      if(s.taken) return;document.querySelectorAll('.slot').forEach(n=>n.classList.remove('selected'));
      chosenSlot=s;el.classList.add('selected');
    }
    renderSlots();

    document.getElementById('holdPrivate').addEventListener('click',()=>{
      if(!chosenSlot){alert('Pick a slot to hold.');return}
      // fake hold: mark as taken locally
      const slot = slots.find(x=>x.id===chosenSlot.id);slot.taken=true;renderSlots();alert('Held '+chosenSlot.time+" locally. We'll follow up to confirm and take payment.");
    });

    // mini guided modal
    const modalGuide = document.getElementById('modalGuide');
    document.getElementById('previewGuide').addEventListener('click',()=>{modalGuide.classList.add('show')});
